/**
 * ProfileActivity
 *
 * Displays the user's profile:
 *  - Personal info card (avatar, name, email, membership badge, quick stats)
 *  - Grouped settings menus (iOS-style)
 *  - Floating bottom navigation bar
 */
public class ProfileActivity extends AppCompatActivity {

    // ── Profile Card ──────────────────────────────────────────────────
    private ImageView ivAvatar;
    private View btnEditProfile;
    private TextView  tvProfileName;
    private TextView  tvProfileEmail;
    private TextView  tvMembershipLabel;
    private TextView  tvStreak;
    private TextView  tvXp;
    private TextView  tvHours;

    // ── Menu Rows ─────────────────────────────────────────────────────
    private LinearLayout btnLearningPaths;
    private LinearLayout rowCertificates;
    private LinearLayout rowOrderHistory;
    private LinearLayout rowVouchers;
    private LinearLayout rowPaymentMethods;
    private LinearLayout rowLogout;

    // ── Demo stat data ─────────────────────────────────────────────────
    private static final int STREAK_DAYS  = 14;
    private static final int XP_POINTS    = 2_450;
    private static final int LEARN_HOURS  = 38;

    private UserDto currentUserDto;

    private Uri selectedAvatarUri = null;
    private ImageView dialogAvatarView = null;

    private final ActivityResultLauncher<Intent> imagePickerLauncher = registerForActivityResult(
            new ActivityResultContracts.StartActivityForResult(),
            result -> {
                if (result.getResultCode() == Activity.RESULT_OK && result.getData() != null) {
                    selectedAvatarUri = result.getData().getData();
                    if (dialogAvatarView != null) {
                        Glide.with(this)
                                .load(selectedAvatarUri)
                                .circleCrop()
                                .into(dialogAvatarView);
                    }
                }
            });

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_profile);

        bindViews();
        // Fallback demo data
        populateUserData();

        // Fetch real data
        fetchUserProfile();

        setupMenuListeners();
        setupEditProfileListener();

        boolean isInstructorView = getIntent().getBooleanExtra("IS_INSTRUCTOR_VIEW", false);
        View navStudent = findViewById(R.id.navStudent);
        View navInstructor = findViewById(R.id.navInstructor);

        if (isInstructorView || "INSTRUCTOR".equalsIgnoreCase(UserManager.getInstance().getUserRole())) {
            if (navStudent != null) navStudent.setVisibility(View.GONE);
            if (navInstructor != null) navInstructor.setVisibility(View.VISIBLE);

            NavHelper.setupInstructorNavigation(this, R.id.navInstProfile);
        } else {
            if (navStudent != null) navStudent.setVisibility(View.VISIBLE);
            if (navInstructor != null) navInstructor.setVisibility(View.GONE);

            NavHelper.setupNavigation(this, R.id.navProfile);
        }
    }

    // ─────────────────────────────────────────────────────────────────
    // View binding
    // ─────────────────────────────────────────────────────────────────

    private void bindViews() {
        ivAvatar          = findViewById(R.id.ivAvatar);
        btnEditProfile = findViewById(R.id.btnEditProfile);
        tvProfileName     = findViewById(R.id.tvProfileName);
        tvProfileEmail    = findViewById(R.id.tvProfileEmail);
        tvMembershipLabel = findViewById(R.id.tvMembershipLabel);
        tvStreak          = findViewById(R.id.tvStreak);
